func serviceUnionChapter(t testing.TB) string {
	t.Helper()
	chapter := servicesRulesChapter(t)
	for _, rule := range serviceUnionRules {
		if !strings.Contains(chapter, rule.quote) {
			t.Fatalf("chapter 5 no longer says %q", rule.quote)
		}
	}
	return chapter
}

func TestServiceKeyUnionsQuoted(t *testing.T) { serviceUnionChapter(t) }

func FuzzServiceKeyUnions(f *testing.F) {
	startShortBudget(f)
	chapter := serviceUnionChapter(f)
	for _, rule := range serviceUnionRules {
		f.Add([]byte(rule.key))
		f.Add([]byte(rule.key + "\x00\x03"))
	}
	w := NewWorkspace(f)
	f.Fuzz(func(t *testing.T, data []byte) {
		parts := strings.SplitN(string(data), "\x00", 2)
		choice := 0
		if len(data) != 0 {
			choice = int(data[0]) % len(serviceUnionRules)
		}
		for i, rule := range serviceUnionRules {
			if parts[0] == rule.key {
				choice = i
				break
			}
		}
		rule := serviceUnionRules[choice]
		if len(parts) == 2 && len(parts[1]) > 0 {
			variant := parts[1][0]
			if variant&1 != 0 {
				rule.good = "// retained trivia\n" + strings.NewReplacer("S", "SCafé", "T", "TCafé").Replace(rule.good)
				rule.bad = "// retained trivia\n" + strings.NewReplacer("S", "SCafé", "T", "TCafé").Replace(rule.bad)
			}
			if variant&2 != 0 {
				rule.good = strings.ReplaceAll(rule.good, "\"", "'")
				rule.bad = strings.ReplaceAll(rule.bad, "\"", "'")
			}
		}
		var compileErrors []string
		var errorCodes map[int32]bool
		compile := func(source string) bool {
			compileErrors = nil
			errorCodes = map[int32]bool{}
			r, err := w.Compile(t.Context(), Project{Files: map[string]string{"main.vibe": source + "\n", "package.json": servicesPackage, "foreign-contracts.ts": "export type ForeignCallback<E> = {\n/** @throws {E} */\n(): number\n}\n"}})
			if err != nil {
				t.Fatal(err)
			}
			defer r.Remove()
			for _, d := range r.Diagnostics {
				if d.Category() == diagnostics.CategoryError {
					compileErrors = append(compileErrors, fmt.Sprintf("%s%d: %s", d.Source(), d.Code(), d.String()))
					if IsEK(d) {
						errorCodes[d.Code()] = true
					}
				}
			}
			return len(compileErrors) == 0
		}
		if !compile(rule.good) {
			Gap(t, "FuzzServiceKeyUnions", "control:"+rule.key, "chapter 5: %s; valid control does not compile:\n%s\n%s", rule.quote, rule.good, strings.Join(compileErrors, "\n"))
			return
		}
		if compile(rule.bad) {
			Gap(t, "FuzzServiceKeyUnions", "reject:"+rule.key, "chapter 5: %s; forbidden form compiled:\n%s", rule.quote, rule.bad)
			return
		}
		if expected := servicesRuleDiagnostic(chapter, rule.quote); !errorCodes[expected] {
			Gap(t, "FuzzServiceKeyUnions", "diagnostic:"+rule.key, "chapter 5 requires EK%04d for %s; got:\n%s", expected, rule.key, strings.Join(compileErrors, "\n"))
			return
		}
		ExpectPending(t, "FuzzServiceKeyUnions", "control:"+rule.key)
		ExpectPending(t, "FuzzServiceKeyUnions", "reject:"+rule.key)
		ExpectPending(t, "FuzzServiceKeyUnions", "diagnostic:"+rule.key)
		ExpectPending(t, "FuzzServiceKeyUnions", specCorpusKey(t))
	})
}
